(* Emoji dataset + search — bindings over the bundled @emoji-mart/data
   and emoji-mart npm packages (cljs ui.cljs + icon.cljs). init must run
   once before <em-emoji> elements render glyphs or SearchIndex works. *)

(* The dataset ships as resources/js/emoji-data.js (generated by
   scripts/gen-emoji-data.mjs from @emoji-mart/data's native set) and is
   loaded by index.html before main.js — same pattern as icon-data.js. *)
open Promise_ext
external emoji_data : Js.Json.t Js.Undefined.t = "__emojiData"
  [@@mel.scope "window"]

let data_prop (k : string) : Js.Json.t =
  match Js.Undefined.toOption emoji_data with
  | None -> failwith "emoji_mart: __emojiData missing (emoji-data.js not loaded)"
  | Some d -> (
      match Js.Json.decodeObject d with
      | Some dict -> (
          match Js.Dict.get dict k with
          | Some v -> v
          | None -> failwith ("emoji_mart: __emojiData." ^ k ^ " missing"))
      | None -> failwith "emoji_mart: __emojiData is not an object")

(* lazy — window.__emojiData is absent under node tests *)
let mart_categories = lazy (data_prop "categories")
let mart_emojis = lazy (data_prop "emojis")
let mart_aliases = lazy (data_prop "aliases")
let mart_sheet = lazy (data_prop "sheet")

(* the npm lib ships as a lazy chunk (shims/lazy_assets.mjs
   loadEmojiMart) — a literal require would pull it into main.js, so
   init/search reach the module through the memoized promise. <em-emoji>
   elements render unupgraded until init lands, then the browser
   upgrades them — so boot fires and forgets. *)
external raw_require : string -> Js.Json.t = "require"

external shim_load_emoji_mart : Js.Json.t -> Js.Json.t Js.Promise.t
  = "loadEmojiMart"
  [@@mel.send]

external mart_init : Js.Json.t -> Js.Json.t -> unit = "init"
  [@@mel.send]

external mart_search_index : Js.Json.t -> Js.Json.t = "SearchIndex"
  [@@mel.get]

external mart_search :
  Js.Json.t -> string -> Js.Json.t array Js.Promise.t
  = "search" [@@mel.send]

let mart_load =
  lazy
    (shim_load_emoji_mart (raw_require "lui-shims/lazy-assets")
     |> Js.Promise.then_ (fun m ->
            let data = Js.Dict.empty () in
            Js.Dict.set data "categories" (Lazy.force mart_categories);
            Js.Dict.set data "emojis" (Lazy.force mart_emojis);
            Js.Dict.set data "aliases" (Lazy.force mart_aliases);
            Js.Dict.set data "sheet" (Lazy.force mart_sheet);
            let opts = Js.Dict.empty () in
            Js.Dict.set opts "data" (Js.Json.object_ data);
            mart_init m (Js.Json.object_ opts);
            Js.Promise.resolve m))

let install () = ignore (Lazy.force mart_load)

(* frontend.reaction/emoji-id-valid? *)
let emoji_id_valid (id : string) : bool =
  id <> ""
  &&
  match Js.Json.decodeObject (Lazy.force mart_emojis) with
  | Some dict -> Js.Dict.get dict id <> None
  | None -> false

let json_str (j : Js.Json.t) (k : string) : string option =
  Js.Json.decodeString (Web_dom.js_get j k)

(* search entries arrive as {id, name, skins} *)
let entry_of_json (j : Js.Json.t) : (string * string) option =
  match json_str j "id" with
  | Some id -> Some (id, Option.value (json_str j "name") ~default:id)
  | None -> None

(* search a query; resolves to (id, name) pairs *)
let search (q : string) (f : (string * string) list -> unit) =
  if String.trim q = "" then f []
  else
    ignore
      ((let* m = Lazy.force mart_load in
       let* arr = mart_search (mart_search_index m) q in
       Js.Promise.resolve
         (f (List.filter_map entry_of_json (Array.to_list arr))))
      |> Js.Promise.catch (fun e ->
             Platform.console_error ("emoji search failed", e);
             Js.Promise.resolve (f [])))
